/**
 * 乱码修复工具数据表（自动生成，勿手改）。
 * 生成：python scripts/gen-encode-tables.py
 *
 * 1) GBK 编码回转表：把"UTF-8 被误读为 GBK"的文本编码回转成原始字节。
 *    UNI 为升序码点表（显式小端），SEQ 为对应 GBK 双字节序列；运行期二分查找。
 *    条目数：21791
 * 2) GB2312 一级常用字位图（区间 [0x4E00, 0x9FA5]，3755 字）：
 *    修复质量判别——正确解码的中文几乎全是一级常用字，误读垃圾字大量落在区间外。
 */

const GBK_UNI_B64 =
	"";
const GBK_SEQ_B64 =
	"";
const L1_BITSET_B64 =
	"";

function b64ToBytes(b64: string): Uint8Array {
	const bin = typeof atob === "function" ? atob(b64) : Buffer.from(b64, "base64").toString("binary");
	const out = new Uint8Array(bin.length);
	for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
	return out;
}

// 显式小端组装，避免 Uint16Array 平台字节序差异
const GBK_UNI = (() => {
	const b = b64ToBytes(GBK_UNI_B64);
	const u = new Uint16Array(b.length / 2);
	for (let i = 0; i < u.length; i++) u[i] = b[i * 2] | (b[i * 2 + 1] << 8);
	return u;
})();
const GBK_SEQ = b64ToBytes(GBK_SEQ_B64);
const L1_BITS = b64ToBytes(L1_BITSET_B64);
const L1_LO = 0x4E00;
const L1_HI = 0x9FA5;

/** 单个字符编码回转为 GBK 字节；无映射返回 null */
export function charToGbk(code: number): Uint8Array | null {
	let lo2 = 0;
	let hi2 = GBK_UNI.length - 1;
	while (lo2 <= hi2) {
		const mid = (lo2 + hi2) >> 1;
		const v = GBK_UNI[mid];
		if (v === code) return GBK_SEQ.subarray(mid * 2, mid * 2 + 2);
		if (v < code) lo2 = mid + 1;
		else hi2 = mid - 1;
	}
	return null;
}

/** 是否 GB2312 一级常用汉字 */
export function isCommonHanzi(code: number): boolean {
	if (code < L1_LO || code > L1_HI) return false;
	const i = code - L1_LO;
	return (L1_BITS[i >> 3] & (1 << (i & 7))) !== 0;
}
